void schedule_functor(vvp_gen_event_t obj)
{
      struct generic_event_s*cur = new generic_event_s;

      cur->obj = obj;
      cur->delete_obj_when_done = false;
      if (!sim_started) {
            schedule_init_event(cur);
      } else {
            schedule_event_(cur, 0, SEQ_ACTIVE);
      }
}
